/** Geist's average lowercase advance in em: the width of a character the table does not hold. */
const AVERAGE_EM = 0.57;

/** Letters without a canonical decomposition, measured as the ASCII letter they are drawn from. */
const LATIN_BASES: Record<string, string> = {
	Đ: "D",
	đ: "d",
	Ł: "L",
	ł: "l",
	Ø: "O",
	ø: "o",
	ı: "i",
	ħ: "h",
};

/** A character's advance in em at the weight's widths: printable ASCII and the Latin letters built on it, else the average. */
function advance(char: string, widths: readonly number[]): number {
	const base = LATIN_BASES[char] ?? char.normalize("NFD")[0] ?? char;
	const code = base.codePointAt(0) ?? 0;
	const width = code >= 32 && code <= 126 ? widths[code - 32] : undefined;
	return width === undefined ? AVERAGE_EM : width / 1000;
}

/** The width in pixels of `text` in Geist at `size` pixels; weights 400, 500 and 600 are measured, others use the nearest below. */
export function textWidth(text: string, size: number, weight = 400): number {
	const widths = GEIST_WIDTHS[weight >= 600 ? 600 : weight >= 500 ? 500 : 400] ?? [];
	let em = 0;
	for (const char of text) {
		em += advance(char, widths);
	}
	return em * size;
}
